-- [S7] Water (NPDES) enforcement for every NPDES permit FRS links to the 18 plants: formal actions (all dates) and informal actions since 2015, plus quarters in noncompliance since 2015
WITH ids AS (SELECT column1 AS NPDES_ID FROM VALUES ('IA0003441'),('IN0059641'),('INR10H048'),('INRA02726'),('INRA03535'),('INRA11911'),('INRM00667'),('NE0000787'),('NE0130141'),('NE0131539'),('NE0131679'),('NE0133850'),('NE0134261'),('NE0137707'),('NE0137715'),('NE0137804'),('NE0137839'),('NER000338'),('NEU001115')),
fa AS (SELECT NPDES_ID, COUNT(*) AS FORMAL_ALL, COUNT_IF(SETTLEMENT_ENTERED_DATE >= '2015-01-01') AS FORMAL_15, SUM(COALESCE(FED_PENALTY_ASSESSED_AMT,0)+COALESCE(STATE_LOCAL_PENALTY_AMT,0)) AS PEN_ALL,
   LISTAGG(AGENCY || ':' || COALESCE(TO_VARCHAR(SETTLEMENT_ENTERED_DATE),'nodate') || ':' || ENF_TYPE_DESC || ':$' || TO_VARCHAR(COALESCE(FED_PENALTY_ASSESSED_AMT,0)+COALESCE(STATE_LOCAL_PENALTY_AMT,0)), ' | ') WITHIN GROUP (ORDER BY SETTLEMENT_ENTERED_DATE) AS FA_LIST
   FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_NPDES_NPDES_FORMAL_ENFORCEMENT_ACTIONS WHERE NPDES_ID IN (SELECT NPDES_ID FROM ids) GROUP BY 1),
ia AS (SELECT NPDES_ID, COUNT(*) AS INF_15, LISTAGG(DISTINCT ENF_TYPE_DESC, ';') AS INF_TYPES FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_NPDES_NPDES_INFORMAL_ENFORCEMENT_ACTIONS WHERE ACHIEVED_DATE >= '2015-01-01' AND NPDES_ID IN (SELECT NPDES_ID FROM ids) GROUP BY 1),
q AS (SELECT NPDES_ID, COUNT(*) AS QTRS, COUNT_IF(HLRNC IS NOT NULL AND HLRNC NOT IN ('','C','0')) AS QTRS_NONCOMP, LISTAGG(DISTINCT HLRNC, ',') AS HLRNC_VALS, SUM(TRY_TO_NUMBER(NUME90_Q)) AS EFFLUENT_EXCEED
   FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_NPDES_NPDES_QNCR_HISTORY WHERE NPDES_ID IN (SELECT NPDES_ID FROM ids) AND LEFT(YEARQTR,4) >= '2015' GROUP BY 1)
SELECT ids.NPDES_ID, fa.FORMAL_ALL, fa.FORMAL_15, fa.PEN_ALL, ia.INF_15, ia.INF_TYPES, q.QTRS, q.QTRS_NONCOMP, q.HLRNC_VALS, q.EFFLUENT_EXCEED, fa.FA_LIST
FROM ids LEFT JOIN fa USING (NPDES_ID) LEFT JOIN ia USING (NPDES_ID) LEFT JOIN q USING (NPDES_ID) ORDER BY 1
